CREATE FUNCTION public.generate_12digit_id() RETURNS bigint
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Generates a 12-digit unique number based on timestamp
    RETURN (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT % 100000000000 + 100000000000;
END;
$$;


